# Expand partial demo outputs to their full dimensions.
def tile_rows(rows,n): return [rows[i%len(rows)] for i in range(n)]
demos[0]=(demos[0][0],tile_rows(demos[0][1],10))
demos[2]=(demos[2][0],tile_rows(demos[2][1],9))
demos[7]=(demos[7][0],tile_rows(demos[7][1],9))
# Candidate color=base[f][g]. Enumerate simple coordinate transforms.
def vals(r,c,H,W,h,w):
    return dict(r=r,c=c,H=H,W=W,h=h,w=w,i=r%h,j=c%w,tr=r//h,tc=c//w,
                R=r*h//H,C=c*w//W)
exprs={
'i':lambda v:v['i'],'tr':lambda v:v['tr'],'R':lambda v:v['R'],
'i+tr':lambda v:v['i']+v['tr'],'i*tr':lambda v:v['i']*v['tr'],
'tr+tc':lambda v:v['tr']+v['tc'],'i+j':lambda v:v['i']+v['j'],
'R+tr':lambda v:v['R']+v['tr'],'R+i':lambda v:v['R']+v['i'],
'r//h2':lambda v:v['r']//(v['h']**2),'r//w':lambda v:v['r']//v['w'],
'floor(r/2)':lambda v:v['r']//2,'r':lambda v:v['r'],
'zero':lambda v:0,
}
jexprs={
'j':lambda v:v['j'],'tc':lambda v:v['tc'],'C':lambda v:v['C'],
'j+tc':lambda v:v['j']+v['tc'],'j*tc':lambda v:v['j']*v['tc'],
'tr+tc':lambda v:v['tr']+v['tc'],'i+j':lambda v:v['i']+v['j'],
'C+tc':lambda v:v['C']+v['tc'],'C+j':lambda v:v['C']+v['j'],
'c//w2':lambda v:v['c']//(v['w']**2),'c//h':lambda v:v['c']//v['h'],
'floor(c/2)':lambda v:v['c']//2,'c':lambda v:v['c'],
'zero':lambda v:0,
}
solutions=[]
for fn,f in exprs.items():
 for gn,g in jexprs.items():
  ok=True
  for base,out in demos:
   h,w=len(base),len(base[0]);H,W=len(out),len(out[0])
   for r in range(H):
    for c in range(W):
     if out[r][c] is None: continue
     v=vals(r,c,H,W,h,w)
     if base[f(v)%h][g(v)%w] != out[r][c]: ok=False;break
    if not ok:break
   if not ok:break
  if ok:solutions.append((fn,gn))
print('solutions',solutions)
# Best scores
scores=[]
for fn,f in exprs.items():
 for gn,g in jexprs.items():
  score=tot=0
  for base,out in demos:
   h,w=len(base),len(base[0]);H,W=len(out),len(out[0])
   for r in range(H):
    for c in range(W):
     if out[r][c] is None:continue
     v=vals(r,c,H,W,h,w);tot+=1
     score+=base[f(v)%h][g(v)%w]==out[r][c]
  scores.append((score/tot,fn,gn))
print(sorted(scores,reverse=True)[:15])

import itertools
# Enumerate T/G coordinate candidates and boolean ops with L=1.
rfuncs={
 'tr':lambda v:v['tr'], 'R':lambda v:v['R'], 'hi':lambda v:v['r']//(v['h']**2),
 'i+tr':lambda v:v['i']+v['tr'],'R+tr':lambda v:v['R']+v['tr'],
 'i*tr':lambda v:v['i']*v['tr'],'i':lambda v:v['i'],
}
cfuncs={
 'tc':lambda v:v['tc'], 'C':lambda v:v['C'], 'hi':lambda v:v['c']//(v['w']**2),
 'j+tc':lambda v:v['j']+v['tc'],'C+tc':lambda v:v['C']+v['tc'],
 'j*tc':lambda v:v['j']*v['tc'],'j':lambda v:v['j'],
}
ops={'T':lambda t,g:t,'G':lambda t,g:g,'and':lambda t,g:t&g,'or':lambda t,g:t|g,
     'xor':lambda t,g:t^g,'notT':lambda t,g:1-t,'notG':lambda t,g:1-g,
     'xnor':lambda t,g:1-(t^g),'nand':lambda t,g:1-(t&g),'nor':lambda t,g:1-(t|g)}
best=[]
for (tn,tf),(gn,gf) in itertools.product(rfuncs.items(),cfuncs.items()):
 for (rn,rf),(cn,cf) in itertools.product(rfuncs.items(),cfuncs.items()):
  # restrict second coord to global-ish to limit
  if rn not in ('R','hi','i','i+tr','R+tr') or cn not in ('C','hi','j','j+tc','C+tc'):continue
  for opn,op in ops.items():
   score=tot=0;ok=True
   for base,out in demos:
    h,w=len(base),len(base[0]);H,W=len(out),len(out[0])
    for r in range(H):
     for c in range(W):
      if out[r][c] is None:continue
      v=vals(r,c,H,W,h,w);tot+=1
      pred=op(base[tf(v)%h][gf(v)%w],base[rf(v)%h][cf(v)%w])
      score+=pred==out[r][c]
      if pred!=out[r][c]:ok=False
   if ok:print('SOLUTION',tn,gn,opn,rn,cn)
   best.append((score/tot,tn,gn,opn,rn,cn))
print(sorted(best,reverse=True)[:20])

sol=[];bs=[]
for X in range(1,20):
 for Y in range(1,20):
  for offx in range(-3,4):
   for offy in range(-3,4):
    score=tot=0;ok=True
    for base,out in demos:
     h,w=len(base),len(base[0]);H,W=len(out),len(out[0])
     for r in range(H):
      for c in range(W):
       if out[r][c] is None:continue
       pred=base[((r+offx)//X)%h][((c+offy)//Y)%w];tot+=1
       score+=pred==out[r][c]
       if pred!=out[r][c]:ok=False
    if ok:sol.append((X,Y,offx,offy))
    bs.append((score/tot,X,Y,offx,offy))
print('sol',sol,'best',sorted(bs,reverse=True)[:10])

